import os
import random
import struct
from typing import List

# Data type: binary string
# See previous reasoning notes; this version fixes edge cases when target_max == 0.

_MAX_SIZE = 4096
_SMALL_MAX = 512

def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(max(0, n)))

def _ascii_text(r: random.Random) -> bytes:
    words = [
        b"hello", b"world", b"kernel", b"log", b"thread", b"queue", b"lane",
        b"memory", b"map", b"protect", b"affinity", b"irq", b"event", b"registers",
        b"hel", b"submit", b"async", b"nop", b"cow", b"slice", b"vm", b"vspace",
    ]
    k = r.randint(3, 10)
    parts: List[bytes] = []
    for _ in range(k):
        w = r.choice(words)
        parts.append(w)
        if r.random() < 0.7:
            parts.append(b" ")
    if r.random() < 0.5:
        parts.append(b"\n")
    if r.random() < 0.2:
        parts.append(b"\x00")
    return b"".join(parts)

def _utf8_sample(r: random.Random) -> bytes:
    cps = [
        0x00A9, 0x03B1, 0x0416, 0x20AC, 0x2603, 0x1F600, 0x1F680, 0x2713, 0x00E9,
    ]
    k = r.randint(3, 12)
    out = bytearray()
    for _ in range(k):
        cp = r.choice(cps)
        out += chr(cp).encode('utf-8')
        if r.random() < 0.3:
            out += b" "
    if r.random() < 0.3:
        out += b"\n"
    return bytes(out)

def _zeros(r: random.Random) -> bytes:
    n = r.choice([0, 1, 2, 4, 8, 16, 32, 64, 128, 256])
    return b"\x00" * n

def _inc_bytes(start: int, n: int) -> bytes:
    if n <= 0:
        return b""
    return bytes(((start + i) & 0xFF) for i in range(n))

def _pattern_repeat(r: random.Random) -> bytes:
    seed_len = r.randint(1, 16)
    seed = _rand_bytes(r, seed_len)
    reps = r.randint(1, 64)
    return (seed * reps)[: seed_len * reps]

def _structured_header(r: random.Random) -> bytes:
    magic = r.choice([b"HELO", b"HL\x00G", b"REGS", b"DATA"])  # 4 bytes
    pay = r.randint(0, 256)
    flags = r.getrandbits(32)
    hdr = magic + struct.pack('<I', pay) + struct.pack('<I', flags)
    payload = _rand_bytes(r, pay)
    return hdr + payload

def _sg_mix(r: random.Random, target_max: int) -> bytes:
    # When target_max == 0, return empty early to avoid randint errors
    if target_max <= 0:
        return b""
    segs = []
    for _ in range(r.randint(2, 5)):
        choice = r.random()
        if choice < 0.2:
            seg = _ascii_text(r)
        elif choice < 0.4:
            seg = _utf8_sample(r)
        elif choice < 0.55:
            seg = _zeros(r)
        elif choice < 0.75:
            seg = _pattern_repeat(r)
        elif choice < 0.9:
            seg = _structured_header(r)
        else:
            upper = min(256, max(1, target_max))
            n = r.randint(1, upper)
            seg = _inc_bytes(r.getrandbits(8), n)
        segs.append(seg)
    data = b"".join(segs)
    if len(data) > target_max:
        data = data[:target_max]
    return data

def _choose_size(r: random.Random) -> int:
    roll = r.random()
    if roll < 0.20:
        return r.choice([0, 1, 2, 3, 4, 5, 7, 11, 13, 17, 31, 63, 127, 255])
    elif roll < 0.90:
        return r.randint(0, _SMALL_MAX)  # allow 0 here
    else:
        return r.randint(0, _MAX_SIZE)   # allow 0 here

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    max_len = _choose_size(r)

    mode = r.random()
    if mode < 0.15:
        data = _ascii_text(r)
    elif mode < 0.30:
        data = _utf8_sample(r)
    elif mode < 0.45:
        data = _pattern_repeat(r)
    elif mode < 0.60:
        data = _structured_header(r)
    elif mode < 0.75:
        n = max_len if max_len > 0 else r.randint(0, 32)
        data = _inc_bytes(r.getrandbits(8), n)
    else:
        data = _sg_mix(r, max_len)

    target = max_len
    if target < 0:
        target = 0

    if len(data) > target:
        data = data[:target]
    elif len(data) < target:
        if target <= _SMALL_MAX and r.random() < 0.6:
            need = target - len(data)
            if need > 0:
                pad_seed = bytes([r.getrandbits(8)])
                data += (pad_seed * need)[:need]
        # else leave shorter; consumer may repeat pattern

    if len(data) > _MAX_SIZE:
        data = data[:_MAX_SIZE]

    return data
